float sdfSphere(vec3 p , float s)
{
    //imagine a sphere is at origin of radius = 1, so it will return this as a result
    return length(p) -s;
}
float smoothMin (float a , float b ,float k)
{
    float h = max ( k - abs(a-b) , 0. ) / k;
    return min (a , b) - h*h*h*k*(1.0/6.0);
}

float map (vec3 p)
{
    vec3 spherePos1 = vec3 ( sin(iTime) * 3. , 0 , 0);
    vec3 spherePos2 = vec3 ( cos(iTime) * 3. , 0 , 0);

    float ground = p.y  + .8;


//    return ground;
  //  return min(ground  ,  sdfSphere(p - spherePos , 1.)  ) ;
   return smoothMin(ground , smoothMin(sdfSphere(p - spherePos2  ,1.)  ,  sdfSphere(p - spherePos1 , 1.)  , 4. ) , .5) ;

}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    //vec2 uv = fragCoord/iResolution.xy;

    // Move Origin (0,0) in the cennter
    vec2 uv = (fragCoord * 2.0- iResolution.xy) / iResolution.y;


    //ray origin
    vec3 ro = vec3 ( 0 , 0 , -3) ; 

    //ray direction
    vec3 rd =  normalize( vec3 (uv , 1)  ); // ray direction passing from each pixel/fragment

    //distance travelled
    float t = 0.0;


    vec3 col;
    //raymarching
    for (int i = 0; i  < 80 ; i++)
    {
        vec3 p  = ro + rd * t;
        float d = map (p);
        t += d;

        //just for visualization of steps
        //col = vec3(i)/80.;


        //for early stopping the raymarch
        if(d < 0.001) break;
        if(d > 100.0) break;
    }




    col = vec3(t * .1); //color based on distance

    // Output to screen
    fragColor = vec4(col,1.0);
}
